      // We'll place sprite after the code. For now use font chars as sprite
      // Use V4 = pointer to our inline sprite data (placed at 0x100)
      0xA6, 0x01,   // LD I, 0x0100

      // Load sprite height from memory[I]
      0xF7, 0x29,   // — we'll use fixed height of 5
      // Draw sprite at V0,V1 with height 5
      0xD0, 0x15,   // DRW V0, V1, 5

      // === MOVEMENT (run every 3 frames to slow it down) ===
      // Check if we should move — use frame counter in V9
      0xF9, 0x07,   // LD V9, DT  ; use delay timer as rough frame count proxy
      0xF9, 0x15,   // LD DT, V9  ; echo back

      // === KEY INPUT ===
      // Check if any key is pressed — if so, react to it
      // SKNP V0: skip next if key V0 NOT pressed (keys are 0-3)
      // Actually let's check specific keys using the keypad mapping:
      // Key layout: 1=0x1, 2=0x2, 3=0x3, C=0xC, 4=0x4, 5=0x5, 6=0x6, D=0xD, Q=0xE, W=0xF, E=0x0, R=0x1 (dup)
      // Standard mapping: keys are V0-V3 for direction
      // We'll check key 0 (keypad '1') for left, key 1 ('2') for right, etc.

      // Check LEFT (key 4 = C on keypad) — if not pressed, skip bounce logic
      // This is getting complex; let's simplify:

      // Simple approach: move in current direction, bounce off walls
      // Add dx to x
      0x80, 0x24,   // ADD V0, V2  (x += dx) — wait, this is wrong opcode
      // Actually: 0x8xy4 = ADD Vx, Vy; VF=carry
      // We need to add V2 to V0: LD V4,V2 then ADD V0,V4
      0x64, 0x00,   // LD V4, 0x00
      0x84, 0x28,   // LD V4, V2  (copy dx to V4) — no, 0x8xy0 = LD Vx,Vy
      // Let me use proper opcodes:
      0xF4, 0x65,   // LD V[4], [I] ? No. LD Vx,[I] means load V0..Vx from memory[I..I+x]
      // That's not what I want. I need LD V4,V2 = copy V2 to V4
      0x84, 0x18,   // ADD V4, V1 — no that adds V1 to V4

      // OK let me just write this more carefully with proper opcodes
      // The issue is I'm mixing up the bytecode. Let me be very precise:
    ]);

    // Place sprite data at 0x0100 (after font at 0x050, before program at 0x200)
    // Sprite: a simple car/ship shape (5x3 pixels)
    const spriteData = new Uint8Array([
      0x18, 0x3C, 0xFF, 0x3C, 0x18,  // sprite pattern (5 rows x 1 byte each)
      0x05,                               // height = 5 (stored at I=0x0105)
    ]);

    for (let i = 0; i < spriteData.length; i++) {
      this.memory[0x0100 + i] = spriteData[i];
    }

    // Now write the actual demo program bytes properly
    const prog = [
      // === INITIALIZATION ===
      0x60, 0x1A,   // LD V0, 26   (x position)
      0x61, 0x0A,   // LD V1, 10   (y position)
      0x62, 0x01,   // LD V2, 1    (dx)
      0x63, 0x01,   // LD V3, 1    (dy)

      // === MAIN LOOP ===
      0xA4, 0x00,   // LD I, 0x0100 (sprite data address)

      // Draw sprite at (V0, V1), height 5
      0xD0, 0x15,   // DRW V0, V1, 5

      // === UPDATE POSITION ===
      // x += dx
      0x80, 0x24,   // ADD V0, V2  (V0 = V0 + V2, VF=carry)
      // Check bounds for x: if V0 >= 60, reverse dx
      0x64, 0x3C,   // LD V4, 60
      0x44, 0x1C,   // SUB V4, V0? No — we need SUB V0,V4 for comparison
      // Instead: SNE V0,V4 (skip if V0 != V4) doesn't help directly
      // Use: CP/V0 >= V4 check via SUB carry
      0x84, 0x35,   // SUBN V4, V0 (V4 = V0 - V4, VF=V0>=V4)
      // VF=1 means V0 >= 60 → need to bounce
      // Let me use simpler approach with SNE

      // Actually let's check: if V0 > 58, flip dx
      0x64, 0x3A,   // LD V4, 58
      0x54, 0x10,   // SNE V4, V1  -- wrong pair

      // Simpler: just check boundaries with subtraction
      // if (V0 > 58) V2 = -V2; similarly for y
      0x84, 0x05,   // SUB V4, V0 (V4=V4-V0, VF=V4>=V0 i.e. 58>=V0)
      // If V0 > 58, VF=0; if V0 <= 58, VF=1

      // Let me just write clean bytecode:
    ];

    // I'll overwrite with a clean program
    const clean = this.buildDemoProgram();
    for (let i = 0; i < clean.length; i++) {
      this.memory[0x200 + i] = clean[i];
    }
  },

  buildDemoProgram() {
    // Return array of CHIP-8 bytecode for the demo
    // Demo: bouncing rectangle that changes color on key press
    const p = [];
    const add = (b) => p.push(b);

    // Init
    add(0x60); add(0x1A);  // LD V0, 26  ; x
    add(0x61); add(0x0A);  // LD V1, 10  ; y
    add(0x62); add(0x01);  // LD V2, 1   ; dx
    add(0x63); add(0x01);  // LD V3, 1   ; dy
    add(0x64); add(0x05);  // LD V4, 5   ; sprite height

    // Loop: draw
    add(0xA5); add(0x00);  // LD I, 0x0100 (sprite data)
    add(0xD0); add(0x14);  // DRW V0, V1, V4

    // Check boundaries and bounce
    // x + dx check: if x >= 58 or x <= 1, reverse dx
    add(0x80); add(0x24);  // ADD V0, V2  (x += dx; VF=carry)
    add(0x65); add(0x3A);  // LD V5, 58   ; max x bound
    add(0x85); add(0x05);  // SUB V5, V0  (V5 = 58-x; VF=58>=x)

    // If x > 58 (VF=0 after SUB), flip dx
    add(0x32); add(0x01);  // SE V2, 1   ; if dx==1
    add(0x16); add(0x00);  // JP .+4       ; skip the next two if dx!=1

    // Boundary collision: check both walls
    // Use SUBN to compare
    add(0x85); add(0x37);  // SUBN V5, V0  (V5 = x-58, VF=x>=58)
    add(0x2F); add(0xFF);  // JP bounce_dx_low

    add(0x46); add(0x01);  // ADD V6, 1    ; V6 = V0+1
    add(0x56); add(0x05);  // SNE V6, V5   ; if x+1 != 58 (i.e. x < 57)
    add(0x2F); add(0xFF);  // JP continue

    // bounce_dx: flip dx direction
    add(0x32); add(0x01);  // SE V2, 1
    add(0x62); add(0xFF);  // LD V2, -1 (0xFF)
    add(0x2F); add(0xFF);  // JP cont

    add(0x32); add(0xFE);  // SE V2, -1
    add(0x62); add(0x01);  // LD V2, 1
    add(0x2F); add(0xFF);  // JP cont

    // Similar for y bounds
    add(0x81); add(0x34);  // ADD V1, V3
    add(0x67); add(0x1E);  // LD V7, 30    ; max y bound (32-2)
    add(0x87); add(0x17);  // SUB V7, V1   ; V7=30-y; VF=30>=y

    add(0x66); add(0x1E);  // LD V6, 30
    add(0x56); add(0x07);  // SNE V6, V1   ; if y!=30
    add(0x2F); add(0xFF);  // JP cont

    // bounce_dy: flip dy
    add(0x33); add(0x01);  // SE V3, 1
    add(0x63); add(0xFF);  // LD V3, -1
    add(0x2F); add(0xFF);  // JP cont

    add(0x33); add(0xFE);  // SE V3, -1
    add(0x63); add(0x01);  // LD V3, 1
    add(0x2F); add(0xFF);  // JP cont

    // Continue: check key input for color change
    // Key 1 (V0&0xF) press → flash
    add(0xE0); add(0x9E);  // SKP V0 ; skip next if key 0 pressed
    add(0x2F); add(0xFF);  // JP cont_nokey

    // Key pressed: flash (set all display pixels briefly)
    add(0x68); add(0xFF);  // LD V8, -1 (all 1s)
    add(0xF8); add(0x55);  // LD [I], V8 (store in memory for reference)

    cont: () => {}; // marker

    // Delay to slow down movement (~60fps / 3 = 20fps)
    add(0xF9); add(0x07);  // LD V9, DT
    add(0x89); add(0x15);  // ADD V9, V1
    add(0xF9); add(0x18);  // LD ST, V9 (use sound timer as delay)

    // Jump back to draw
    add(0x12); add(0xE3);  // JP loop_start (0x203)

    return p;
  },

  // ===== INSTRUCTION DECODING =====
  decode(opcode, pc) {
    const n = (opcode >> 12) & 0xF;
    const x = (opcode >> 8) & 0xF;
    const y = (opcode >> 4) & 0xF;
    const nn = opcode & 0xFF;
    const nnn = opcode & 0x0FFF;

    let mnemonic = '???', operands = '', addr = '';

    switch (opcode & 0xF000) {
      case 0x0000:
        if (opcode === 0x00E0) { mnemonic='CLD'; operands='(clear display)'; }
        else if (opcode === 0x00EE) { mnemonic='RET'; operands='(return from sub)'; }
        else { mnemonic='CLR'; operands=`0x${nnn.toString(16).toUpperCase().padStart(3,'0')}`; }
        break;
      case 0x1000: mnemonic='JP'; operands=`0x${nnn.toString(16).toUpperCase().padStart(3,'0')}`; break;
      case 0x2000: mnemonic='CALL'; operands=`0x${nnn.toString(16).toUpperCase().padStart(3,'0')}`; break;
      case 0x3000: mnemonic='SE';  operands=`V${x}, 0x${nn.toString(16).toUpperCase().padStart(2,'0')}`; break;
      case 0x4000: mnemonic='SNE'; operands=`V${x}, 0x${nn.toString(16).toUpperCase().padStart(2,'0')}`; break;
      case 0x5000: mnemonic='SE';  operands=`V${x}, V${y}`; break;
      case 0x6000: mnemonic='LD';  operands=`V${x}, 0x${nn.toString(16).toUpperCase().padStart(2,'0')}`; break;
      case 0x7000: mnemonic='ADD'; operands=`V${x}, 0x${nn.toString(16).toUpperCase().padStart(2,'0')}`; break;
      case 0x8000:
        switch (n) {
          case 0x0: mnemonic='LD';  operands=`V${x}, V${y}`; break;
          case 0x1: mnemonic='OR';  operands=`V${x}, V${y}`; break;
          case 0x2: mnemonic='AND'; operands=`V${x}, V${y}`; break;
          case 0x3: mnemonic='XOR'; operands=`V${x}, V${y}`; break;
          case 0x4: mnemonic='ADD'; operands=`V${x}, V${y} (VF=carry)`; break;
          case 0x5: mnemonic='SUB'; operands=`V${x}, V${y} (VF=borrow)`; break;
          case 0x6: mnemonic='SHR'; operands=`V${x} >> 1 (VF=LSB)`; break;
          case 0x7: mnemonic='SUBN';operands=`V${x}, V${y} (VF=borrow)`; break;
          case 0xE: mnemonic='SHL'; operands=`V${x} << 1 (VF=MSB)`; break;
        }
        break;
      case 0x9000: mnemonic='SNE'; operands=`V${x}, V${y}`; break;
      case 0xA000: mnemonic='LD I'; operands=`0x${nnn.toString(16).toUpperCase().padStart(3,'0')}`; break;
      case 0xB000: mnemonic='JP V0'; operands=`+ 0x${nnn.toString(16).toUpperCase().padStart(3,'0')}`; break;
      case 0xC000: mnemonic='RND'; operands=`V${x}, 0x${nn.toString(16).toUpperCase().padStart(2,'0')}`; break;
      case 0xD000: mnemonic='DRW'; operands=`V${x}, V${y}, ${n} (VF=collision)`; break;
      case 0xE000:
        if (nn === 0x9E) { mnemonic='SKP';  operands=`V${x}`; }
        else if (nn === 0xA1) { mnemonic='SKNP'; operands=`V${x}`; }
        break;
      case 0xF000:
        switch (nn) {
          case 0x07: mnemonic='LD DT';  operands=`V${x}`; break;
          case 0x0A: mnemonic='WAIT';   operands=`V${x}`; break;
          case 0x15: mnemonic='LD DT,'; operands=`V${x}`; break;
          case 0x18: mnemonic='LD ST,'; operands=`V${x}`; break;
          case 0x1E: mnemonic='ADD I';  operands=`V${x}`; break;
          case 0x29: mnemonic='LD F,';  operands=`V${x} (font)`; break;
          case 0x33: mnemonic='LD BCD'; operands=`V${x}`; break;
          case 0x55: mnemonic='LD [I],';operands=`V${x}`; break;
          case 0x65: mnemonic='LD V[';  operands=`I],V${x}`; break;
        }
        break;
    }

    addr = `0x${pc.toString(16).toUpperCase().padStart(4,'0')}`;
    this.lastDecoded = { mnemonic, operands, addr };
    return { mnemonic, operands, addr, opcode };
  },

  // ===== EXECUTION =====
  executeInstruction() {
    if (this.PC >= 4096 || this.PC < 0x200) return;
    if ((this.PC & 1) !== 0) return; // word-aligned

    const opcode = (this.memory[this.PC] << 8) | this.memory[this.PC + 1];
    const n = (opcode >> 12) & 0xF;
    const x = (opcode >> 8) & 0xF;
    const y = (opcode >> 4) & 0xF;
    const nn = opcode & 0xFF;
    const nnn = opcode & 0x0FFF;

    this.decode(opcode, this.PC);

    switch (opcode & 0xF000) {
      case 0x0000:
        if (opcode === 0x00E0) {
          this.display.fill(0);
          this.PC += 2;
        } else if (opcode === 0x00EE) {
          this.SP--;
          this.PC = this.stack[this.SP] + 2;
        } else {
          // SYS addr — ignore
          this.PC += 2;
        }
        break;

      case 0x1000:
        this.PC = nnn;
        break;

      case 0x2000:
        this.stack[this.SP] = this.PC;
        this.SP++;
        this.PC = nnn;
        break;

      case 0x3000:
        this.PC += (this.V[x] === nn) ? 4 : 2;
        break;

      case 0x4000:
        this.PC += (this.V[x] !== nn) ? 4 : 2;
        break;

      case 0x5000:
        this.PC += (this.V[x] === this.V[y]) ? 4 : 2;
        break;

      case 0x6000:
        this.V[x] = nn;
        this.PC += 2;
        break;

      case 0x7000:
        this.V[x] = (this.V[x] + nn) & 0xFF;
        this.PC += 2;
        break;

      case 0x8000:
        switch (n) {
          case 0x0: this.V[x] = this.V[y]; this.PC += 2; break;
          case 0x1: this.V[x] |= this.V[y]; this.PC += 2; break;
          case 0x2: this.V[x] &= this.V[y]; this.PC += 2; break;
          case 0x3: this.V[x] ^= this.V[y]; this.PC += 2; break;
          case 0x4: {
            const sum = this.V[x] + this.V[y];
            this.V[0xF] = sum > 0xFF ? 1 : 0;
            this.V[x] = sum & 0xFF;
            this.PC += 2;
            break;
          }
          case 0x5: {
            this.V[0xF] = this.V[x] >= this.V[y] ? 1 : 0;
            this.V[x] = (this.V[x] - this.V[y]) & 0xFF;
            this.PC += 2;
            break;
          }
          case 0x6: {
            this.V[0xF] = this.V[x] & 1;
            this.V[x] >>= 1;
            this.PC += 2;
            break;
          }
          case 0x7: {
            this.V[0xF] = this.V[y] >= this.V[x] ? 1 : 0;
            this.V[x] = (this.V[y] - this.V[x]) & 0xFF;
            this.PC += 2;
            break;
          }
          case 0xE: {
            this.V[0xF] = (this.V[x] >> 7) & 1;
            this.V[x] = (this.V[x] << 1) & 0xFF;
            this.PC += 2;
            break;
          }
        }
        break;

      case 0x9000:
        this.PC += (this.V[x] !== this.V[y]) ? 4 : 2;
        break;

      case 0xA000:
        this.I = nnn;
        this.PC += 2;
        break;

      case 0xB000:
        this.PC = nnn + this.V[0];
        break;

      case 0xC000:
        this.V[x] = (Math.floor(Math.random() * 256) & nn);
        this.PC += 2;
        break;

      case 0xD000: {
        const xCoord = this.V[x] % 64;
        const yCoord = this.V[y] % 32;
        this.V[0xF] = 0;
        for (let row = 0; row < n; row++) {
          if (yCoord + row >= 32) break;
          const spriteByte = this.memory[this.I + row];
          for (let col = 0; col < 8; col++) {
            if (xCoord + col >= 64) continue;
            if ((spriteByte & (0x80 >> col)) !== 0) {
              const idx = (yCoord + row) * 64 + (xCoord + col);
              if (this.display[idx] === 1) this.V[0xF] = 1;
              this.display[idx] ^= 1;
            }
          }
        }
        this.PC += 2;
        break;
      }

      case 0xE000:
        if (nn === 0x9E) {
          // SKP Vx: skip if key Vx is pressed
          const keyIdx = this.V[x] & 0xF;
          this.PC += this.keys[keyIdx] ? 4 : 2;
        } else if (nn === 0xA1) {
          // SKNP Vx: skip if key Vx is NOT pressed
          const keyIdx = this.V[x] & 0xF;
          this.PC += !this.keys[keyIdx] ? 4 : 2;
        } else {
          this.PC += 2;
        }
        break;

      case 0xF000:
        switch (nn) {
          case 0x07: // LD Vx, DT
            this.V[x] = this.delayTimer;
            this.PC += 2;
            break;
          case 0x0A: // WAIT Vx — wait for key press
            this.waitingForKey = x;
            this.PC += 2;
            break;
          case 0x15: // LD DT, Vx
            this.delayTimer = this.V[x];
            this.PC += 2;
            break;
          case 0x18: // LD ST, Vx
            this.soundTimer = this.V[x];
            this.PC += 2;
            break;
          case 0x1E: // ADD I, Vx
            this.I = (this.I + this.V[x]) & 0xFFF;
            this.PC += 2;
            break;
          case 0x29: // LD F, Vx (font pointer)
            this.I = 0x050 + (this.V[x] & 0xF) * 5;
            this.PC += 2;
            break;
          case 0x33: // LD BCD, Vx
            const val = this.V[x];
            this.memory[this.I] = Math.floor(val / 100);
            this.memory[this.I + 1] = Math.floor((val % 100) / 10);
            this.memory[this.I + 2] = val % 10;
            this.PC += 2;
            break;
          case 0x55: // LD [I], Vx (store V0..Vx at I)
            for (let i = 0; i <= x; i++) this.memory[this.I + i] = this.V[i];
            this.PC += 2;
            break;
          case 0x65: // LD Vx, [I] (load V0..Vx from I)
            for (let i = 0; i <= x; i++) this.V[i] = this.memory[this.I + i];
            this.PC += 2;
            break;
          default:
            this.PC += 2;
        }
        break;

      default:
        this.PC += 2;
    }

    this.instructionsExecuted++;
  },

  // ===== TIMER UPDATE (60 Hz) =====
  updateTimers() {
    if (this.delayTimer > 0) this.delayTimer--;
    if (this.soundTimer > 0) {
      this.soundTimer--;
      if (this.soundTimer === 1 && this.audioCtx === null) {
        // will play when audio context is created
      }
    }
  },

  playBeep() {
    try {
      if (!this.audioCtx) this.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = this.audioCtx.createOscillator();
      const gain = this.audioCtx.createGain();
      osc.connect(gain);
      gain.connect(this.audioCtx.destination);
      osc.frequency.value = 440;
      osc.type = 'square';
      gain.gain.value = 0.1;
      osc.start();
      osc.stop(this.audioCtx.currentTime + 0.1);
    } catch (e) { /* audio unavailable */ }
  },

  // ===== KEY INPUT =====
  setKey(key, pressed) {
    this.keys[key] = pressed ? 1 : 0;
    if (this.waitingForKey >= 0 && pressed) {
      this.V[this.waitingForKey] = key;
      this.waitingForKey = -1;
    }
  },

  // ===== MAIN LOOP =====
  mainLoop() {
    if (!this.running || this.paused) return;

    const ips = Math.max(1, Math.floor(this.speed / 10));
    for (let i = 0; i < ips; i++) {
      if (this.waitingForKey >= 0) break;
      this.executeInstruction();
    }
    this.updateTimers();

    // Sound timer beep
    if (this.soundTimer > 0 && this.soundTimer <= 3) {
      this.playBeep();
    }

    updateDebugger();
    updateStatus();

    requestAnimationFrame(() => this.mainLoop());
  },

  run() {
    this.running = true;
    this.paused = false;
    document.getElementById('btnRun').classList.add('active');
    document.getElementById('btnPause').disabled = false;
    this.mainLoop();
  },

  pause() {
    this.paused = true;
  },

  resume() {
    this.paused = false;
    this.mainLoop();
  },

  step() {
    if (this.waitingForKey >= 0) return;
    this.executeInstruction();
    this.updateTimers();
    updateDebugger();
  },

  reset() {
    this.running = false;
    this.paused = false;
    this.PC = 0x200;
    this.init();
    updateDebugger();
    updateStatus();
  }
};

// ===== UI FUNCTIONS =====
function toggleRun() {
  if (!CHIP8.running) {
    CHIP8.run();
  }
}

function togglePause() {
  if (CHIP8.paused) {
    CHIP8.resume();
    document.getElementById('btnPause').textContent = '⏸ Pause';
  } else {
    CHIP8.pause();
    document.getElementById('btnPause').textContent = '▶ Resume';
  }
}

function stepOnce() {
  if (CHIP8.running) {
    CHIP8.paused = true;
    document.getElementById('btnPause').textContent = '▶ Resume';
  }
  CHIP8.step();
}

function resetEmu() {
  CHIP8.reset();
  document.getElementById('btnRun').classList.remove('active');
  document.getElementById('btnPause').disabled = true;
  document.getElementById('btnPause').textContent = '⏸ Pause';
}

function updateSpeed() {
  const slider = document.getElementById('speedSlider');
  CHIP8.speed = parseInt(slider.value);
  document.getElementById('speedVal').textContent = CHIP8.speed;
}

function updateDebugger() {
  // Current instruction
  const d = CHIP8.lastDecoded;
  document.getElementById('currentInstr').textContent =
    `${d.mnemonic}  ${d.addr}  ${d.operands}`;

  // Registers V0-VF
  let rH = '';
  for (let i = 0; i < 16; i++) {
    const hex = CHIP8.V[i].toString(16).toUpperCase().padStart(2, '0');
    const dec = CHIP8.V[i];
    const highlighted = (i === (CHIP8.lastDecoded.opcode >> 8 & 0xF)) ? 'color:#ff7b72' : '';
    rH += `<div class="reg-row"><span class="reg-name">V${i.toString(16).toUpperCase()}</span><span class="reg-val" style="${highlighted}">${hex} (${dec})</span></div>`;
  }
  document.getElementById('regDisplay').innerHTML = rH;

  // Special registers
  document.getElementById('regI').textContent = `0x${CHIP8.I.toString(16).toUpperCase().padStart(4, '0')}`;
